  Stage_140299_Desc = {
    Text = "จงเบ่งบาน จงโบยบิน\nเธอตัดสินใจแล้วว่าไม่ว่าเส้นทางข้างหน้าจะยากลำบากเพียงใด เธอจะไม่มีวันเลือกปล่อยมือเธอ\nในวินาทีที่เราจากกัน ให้ 「ความจริง」 เติมเต็มโลกที่ผิดเพี้ยนนี้"
  },
  Stage_140299_Name = {
    Text = "การร่ำลา"
  },
  Stage_140300_Desc = {
    Text = "ความทรงจำเปรียบดั่งเมล็ดพันธุ์ มันซ่อนสรรพสิ่งไว้ภายใน แต่ปิดเป็นความลับ\nจนกว่าการรดน้ำจะทำให้มันหยั่งรากงอกงาม จนกว่าผืนดินจะโอบรับมัน อนุญาตให้มันดูดซับพลังจากความเป็นจริง"
  },
