  Stage_23639_Name = {
    Text = "ความใจกว้างของพ่อค้า"
  },
  Stage_23640_Desc = {
    Text = "ทุกคนต่างก็มีเรื่องราวซ่อนอยู่ แต่ไม่ใช่ทุกคนที่มีความปรารถนาจะเล่า"
  },
  Stage_23640_Name = {
    Text = "ค้นหาเรื่องราว"
  },
  Stage_23641_Desc = {
    Text = "ดอกไม้ที่ดีที่สุด สร้างสรรค์บทกวีที่งดงามที่สุด"
  },
  Stage_23641_Name = {
    Text = "ดอกไม้ที่ดีที่สุด"
  },
  Stage_23642_Desc = {
    Text = "คนที่คิดถึงมากที่สุด มอบความปรารถนาที่อยากพูดออกไปมากที่สุด"
  },
  Stage_23642_Name = {
    Text = "คนที่คิดถึงมากที่สุด"
  },
  Stage_23643_Desc = {
