  Stage_51761_Desc = {
    Text = "ครั้งสุดท้ายที่เธอจ้องมองไปยังตำแหน่งที่เคยมีรูปปั้นของพระราชาตั้งอยู่ \n ที่นั่นไม่มีรูปปั้น และไม่มีพระราชา."
  },
  Stage_51761_Name = {
    Text = "ฝันถึงลีมูเรีย"
